drop all objects;
create table users(id uuid primary key,email varchar(255) not null unique,password_hash varchar(255),full_name varchar(150) not null,phone varchar(20),role_code varchar(30) default 'CUSTOMER',status varchar(20) default 'ACTIVE',last_login_at timestamp,anonymized_at timestamp,version bigint default 1,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp);
create table user_identities(id uuid default random_uuid() primary key,user_id uuid not null,provider varchar(30),provider_subject varchar(255),provider_email varchar(255),last_login_at timestamp,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp,unique(provider,provider_subject));
create table addresses(id uuid primary key,user_id uuid not null,receiver_name varchar(150),phone varchar(20),province_name varchar(100),district_name varchar(100),ward_name varchar(100),address_line varchar(255),is_default boolean default false,created_at timestamp default current_timestamp,updated_at timestamp default current_timestamp);
create table refresh_tokens(id uuid default random_uuid() primary key,user_id uuid not null,token_hash char(64) unique,expires_at timestamp,revoked_at timestamp,revocation_reason varchar(30),created_at timestamp default current_timestamp);
create table password_reset_tokens(id uuid default random_uuid() primary key,user_id uuid not null,token_hash char(64) unique,expires_at timestamp,used_at timestamp,created_at timestamp default current_timestamp);
